(()=>{
const heroId=new URLSearchParams(location.search).get('hero')||'garnet',hero=HeroData.heroes.find(h=>h.id===heroId&&h.rarity);if(!hero){location.replace('characters.html');return}try{if(!Onboarding.owned(localStorage).includes(heroId)){location.replace('characters.html');return}}catch{location.replace('characters.html');return}document.title=hero.name+'的星盤';document.querySelector('.hero img').src=hero.portrait;document.querySelector('.hero img').alt=hero.name;document.querySelector('.hero small').textContent=hero.rarity+' · '+hero.role;document.querySelector('.hero h1').textContent=hero.name+'的星盤';document.querySelector('.core').textContent=hero.name.split(' ').at(-1);
const S=Starboard.forHero(hero),q=s=>document.querySelector(s);let state=S.empty(),storage=null,blocked=false,pending=[],scale=1;
function refresh(){try{storage=localStorage;state=S.load(storage);blocked=false}catch{blocked=true;q('#notice').textContent='無法讀取養成資料，暫停培養以保護進度。'}render()}
function summary(s){const base=hero.stats||BattleRules.stats[hero.battle.type],u={id:hero.battleId,variant:hero.battle.variant,hp:base.hp,max:base.hp};HeroGrowth.apply(u,{...s,unlocked:heroId==='garnet'?s.unlocked:[],...(heroId==='garnet'?{}:{starboards:{...s.starboards,[heroId]:s.unlocked}})});return `攻擊 ${u.dmg.toFixed(2)} · 生命 ${u.max} · 護甲 ${(u.armor*100).toFixed(1)}%`}
const positions=S.nodes.map(n=>{const angle=-Math.PI/2+n.branch*Math.PI*2/5+Math.sin(n.depth*1.6)*.035,r=115+n.depth*53;return {x:700+Math.cos(angle)*r,y:700+Math.sin(angle)*r}});
function render(){q('#balance').textContent=`星輝碎片 ${state.shards}`;q('#level').textContent=`Lv.${1+state.unlocked.length} / 50 · 已解鎖 ${state.unlocked.length} / 49`;q('#stats').textContent=summary(state);q('#nodes').replaceChildren();q('#links').replaceChildren();S.nodes.forEach((n,i)=>{const p=positions[i],parent=n.requires?positions[S.nodes.findIndex(x=>x.id===n.requires)]:{x:700,y:700},line=document.createElementNS('http://www.w3.org/2000/svg','line');Object.entries({x1:parent.x,y1:parent.y,x2:p.x,y2:p.y,stroke:state.unlocked.includes(n.id)?'#edc27b':'#52717c','stroke-width':3}).forEach(([k,v])=>line.setAttribute(k,v));q('#links').append(line);const b=document.createElement('button'),done=state.unlocked.includes(n.id),available=!n.requires||state.unlocked.includes(n.requires);b.className=`node ${n.type==='key'?'key':''} ${done?'unlocked':available?'available':''}`;b.style.left=p.x+'px';b.style.top=p.y+'px';b.dataset.id=n.id;b.setAttribute('aria-label',`${S.branches[n.branch][0]}分支 ${n.title} ${done?'已解鎖':available?'可培養':'未解鎖'}`);b.innerHTML=`${n.type==='key'?'✦':n.title}<span class="mark">${done?'✓':available?'○':'◇'}</span>`;b.onclick=()=>open([n.id]);q('#nodes').append(b)});q('#batch').disabled=blocked||!S.batch(state).length}
function open(ids){pending=ids;q('#title').textContent=ids.length===1?S.nodes.find(n=>n.id===ids[0]).title:'一鍵培養';q('#description').textContent=ids.map(id=>{const n=S.nodes.find(n=>n.id===id);return `${S.branches[n.branch][0]}：${n.effect}`}).join('、');q('#cost').textContent=`消耗 ${ids.reduce((s,id)=>s+S.nodes.find(n=>n.id===id).cost,0)} 星輝碎片`;q('#confirm').disabled=true;q('#change').textContent='';try{if(blocked)throw Error('目前無法儲存');if(ids.some(id=>state.unlocked.includes(id)))throw Error('已解鎖');const {next}=S.quote(state,ids);q('#change').textContent=`Lv.${1+state.unlocked.length} → Lv.${1+next.unlocked.length}；${summary(state)} → ${summary(next)}`;q('#condition').textContent='確認後自動保存';q('#confirm').disabled=false}catch(e){q('#condition').textContent=e.message}q('#detail').showModal()}
q('#cancel').onclick=()=>q('#detail').close();q('#batch').onclick=()=>open(S.batch(state));
q('#confirm').onclick=async()=>{q('#confirm').disabled=true;try{const commit=()=>{state=S.purchase(storage,state,pending)};if(navigator.locks)await navigator.locks.request(S.key,commit);else commit();q('#detail').close();q('#notice').textContent='培養完成，進度已保存。';render()}catch(e){q('#detail').close();q('#notice').textContent='未完成培養：'+e.message;refresh()}};
window.addEventListener('storage',e=>{if(e.key===S.key){q('#detail').close();refresh()}});
function center(){q('#viewport').scrollLeft=700*scale-q('#viewport').clientWidth/2;q('#viewport').scrollTop=700*scale-q('#viewport').clientHeight/2}
function zoom(delta){scale=Math.max(.9,Math.min(1.5,scale+delta));q('#map').style.zoom=scale;center()}
q('#zoom-in').onclick=()=>zoom(.1);q('#zoom-out').onclick=()=>zoom(-.1);q('#center').onclick=center;
let drag;const viewport=q('#viewport');viewport.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&!e.target.closest('button')){drag={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};viewport.setPointerCapture(e.pointerId)}});viewport.addEventListener('pointermove',e=>{if(drag){viewport.scrollLeft=drag.left-(e.clientX-drag.x);viewport.scrollTop=drag.top-(e.clientY-drag.y)}});viewport.addEventListener('pointerup',()=>drag=null);viewport.addEventListener('pointercancel',()=>drag=null);
refresh();requestAnimationFrame(center);
})();
